/* Only a focused answer is returned. Developer records never enter the browser. */
(()=>{'use strict';let available=null;async function answer(raw){const question=String(raw||'').trim();if(!question)return null;try{const r=await fetch('/api/helper',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question}),signal:AbortSignal.timeout(15000)});if(!r.ok)return null;const d=await r.json();available=true;return d.answer||null;}catch{available=false;return null;}}window.FranklinDeveloperKB={answer,load:async()=>null,status:()=>({serverSide:true,available})};})();
